import os

def compress_file(path: str) -> str:
    # Check if the file exists
    if not os.path.exists(path):
        raise FileNotFoundError(f"File {path} does not exist.")

    # Get the file extension
    _, ext = os.path.splitext(path)

    # Define the compression command based on the file extension
    if ext.lower() == '.txt':
        command = f"zip -r {path}.zip {path}"
    elif ext.lower() in ['.jpg', '.jpeg', '.png']:
        command = f"zip -r {path}.zip {path}"
    elif ext.lower() in ['.mp3', '.wav', '.ogg']:
        command = f"ffmpeg -i {path} -c:a libmp3lame {path}.mp3"
    else:
        return "Unsupported file type."

    # Execute the compression command
    try:
        os.system(command)
        return f"File {path} compressed to {path}.zip"
    except Exception as e:
        return f"Error compressing file: {e}"
