        elif token == '*':
            return parse_and_evaluate(tokens) * parse_and_evaluate(tokens)
        elif token == '/':
            return parse_and_evaluate(tokens) // parse_and_evaluate(tokens)

    # Tokenize the input expression
    tokens = expr.replace(' ', '').split()

    # Evaluate the parsed expression
    return parse_and_evaluate(tokens)
