from collections import *

def digital_root_sequence(n: int) -> list[int]:
    def digital_root(x: int) -> int:
        while x >= 10:
            x = sum(int(digit) for digit in str(x))
        return x

    sequence = [n]
    current = n
    while True:
        current = digital_root(current)
        if current in sequence:
            break
        sequence.append(current)

    return sequence

