def caesar_cipher(text: str, shift: int) -> str:
    def shift_char(c: str, base: str, shift: int) -> str:
        if c in base:
            new_index = (base.index(c) + shift) % len(base)
            return base[new_index]
        return c

    lower_shifted = ''.join(shift_char(c, ascii_lowercase, shift) for c in text)
    upper_shifted = ''.join(shift_char(c, ascii_uppercase, shift) for c in text)

