            if op == '+':
                result += next_term
            elif op == '-':
                result -= next_term
            else:
                raise ValueError(f"Invalid operator: {op}")
        return result

    # Tokenize the input expression
    tokens = list(expression.replace(' ', ''))
    tokens.insert(0, '(')  # Add a leading parenthesis to handle the entire expression
    tokens.append(')')   # Add a trailing parenthesis to handle the entire expression

    # Evaluate the expression
    return parse_expression(tokens)
