from typing import List

def shortest_path_one_break(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_row, start_col):
        queue = [(start_row, start_col, 0)]
        visited = set()

        while queue:
            row, col, steps = queue.pop(0)

            if grid[row][col] == 'X':
                return steps

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc

                if 0 <= new_row < rows and 0 <= new_col < cols and (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col, steps + 1))

        return float('inf')

    min_steps = float('inf')

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                # Try breaking at each cell
                for k in range(rows):
                    for l in range(cols):
                        if grid[k][l] == 'X' and (k, l) != (i, j):
                            steps = bfs(i, j) + bfs(k, l)
                            min_steps = min(min_steps, steps)

    return min_steps if min_steps != float('inf') else -1
```

This function calculates the shortest path from any 'S' to any 'X' in the grid, allowing for exactly one break (i.e., passing through an 'X'). It uses a breadth-first search (BFS) approach to explore all possible paths and keeps track of the minimum number of steps required. If no valid path is found, it returns -1.

