from typing import List, Tuple

def tokenize_code(source: str) -> List[Tuple[str, str]]:
    tokens = []
    line_number = 1
    in_string = False
    string_type = None

    for char in source:
        if char == '\n':
            line_number += 1
            in_string = False
            string_type = None
        elif char == '"':
            if not in_string:
                in_string = True
                string_type = 'double'
            else:
                if string_type == 'double':
                    tokens.append(('string', f'"{source[source.index('"', source.index('"') + 1):source.rfind('"')]}"'))
                    in_string = False
                    string_type = None
        elif char == "'":
            if not in_string:
                in_string = True
                string_type = 'single'
            else:
                if string_type == 'single':
                    tokens.append(('string', f"'{source[source.index("'", source.index("'") + 1):source.rfind("'')]}'"))
                    in_string = False
                    string_type = None
        elif char.isspace():
            if in_string:
                continue
            tokens.append(('whitespace', char))
        else:
            if in_string:
                continue
            token = ''
            while char.isalnum() or char in ['_', '-']:
                token += char
                char = next(source)
            source.seek(source.tell() - 1)
            tokens.append(('identifier', token))

    return tokens
