def top_k_elements(nums: List[int], k: int) -> List[int]:
    if k == 0:
        return []

    # Use a min-heap to keep track of the top k elements
    min_heap = nums[:k]
    heapq.heapify(min_heap)

    for num in nums[k:]:
        if num > min_heap[0]:
            heapq.heappop(min_heap)
            heapq.heappush(min_heap, num)

    return list(min_heap)
