    Parameters:
    d (dict): The dictionary to search within.
    keys (list): A list of keys to traverse the dictionary.
    default (any, optional): The default value to return if any key is missing. Defaults to None.

    Returns:
    any: The value found at the specified path or the default value if any key is missing.
    """
    current = d
    for key in keys:
        if key in current:
            current = current[key]
        else:
            return default
    return current

