def matches_filter(expression: str, record: Dict[str, any]) -> bool:
    # Split the expression into key and value parts
    parts = expression.split('=')

    if len(parts) != 2:
        raise ValueError("Expression must be in the format 'key=value'")

    key, value = parts

    # Check if the key exists in the record
    if key not in record:
        return False

    # Compare the value with the record's value
    # Use str() to handle different types of values
    return str(record[key]) == str(value)

