from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    # Initialize the board with all cells as empty
    board = [[0] * n for _ in range(n)]

    # Mark blocked cells
    for row, col in blocked:
        board[row][col] = -1

    def is_valid(row: int, col: int) -> bool:
        # Check if the cell is within bounds and not blocked
        return 0 <= row < n and 0 <= col < n and board[row][col] == 0

    def place_queen(row: int, col: int) -> bool:
        # Place a queen at (row, col) and check if it's valid
        if not is_valid(row, col):
            return False

        # Mark the current cell as occupied
        board[row][col] = 1

        # Check all possible directions for placing queens
        for i in range(1, n):
            # Check right diagonal
            if is_valid(row + i, col + i):
                board[row + i][col + i] = 1
            else:
                break

            # Check left diagonal
            if is_valid(row + i, col - i):
                board[row + i][col - i] = 1
            else:
                break

            # Check down
            if is_valid(row + i, col):
                board[row + i][col] = 1
            else:
                break

            # Check up
            if is_valid(row - i, col):
                board[row - i][col] = 1
            else:
                break

        return True

    def backtrack(row: int) -> int:
        # If we've placed all queens, return 1
        if row == n:
            return 1

        count = 0
        # Try placing a queen in each column of the current row
        for col in range(n):
            if place_queen(row, col):
                count += backtrack(row + 1)
                # Backtrack by removing the queen from the current position
                board[row][col] = 0

        return count

    # Start backtracking from the first row
    return backtrack(0)
