            for j in range(len(grid[i])):
                if grid[i][j] >= 4:
                    return False
        return True

    while not is_stable(grid):
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                if grid[i][j] >= 4:
                    # Distribute excess sand to neighboring cells
                    if i > 0:
                        grid[i-1][j] += 1
                    if i < len(grid) - 1:
                        grid[i+1][j] += 1
                    if j > 0:
                        grid[i][j-1] += 1
                    if j < len(grid[i]) - 1:
                        grid[i][j+1] += 1
                    grid[i][j] -= 4

