def convert_base(number: str, from_base: int, to_base: int) -> str:
    if from_base < 2 or from_base > 16 or to_base < 2 or to_base > 16:
        raise ValueError("Base must be between 2 and 16.")

    # Convert number from base from_base to base 10
    decimal_number = 0
    for digit in number:
        if '0' <= digit <= '9':
            value = ord(digit) - ord('0')
        elif 'A' <= digit <= 'F':
            value = ord(digit) - ord('A') + 10
        else:
            raise ValueError(f"Invalid character '{digit}' in input number.")

        decimal_number = decimal_number * from_base + value

    # Convert decimal number to base to_base
    if decimal_number == 0:
        return "0"

    digits = deque()
    while decimal_number > 0:
        remainder = decimal_number % to_base
        if remainder < 10:
            digits.appendleft(str(remainder))
        else:
            digits.appendleft(chr(ord('A') + remainder - 10))
        decimal_number //= to_base

    return ''.join(digits)
