    count = 0
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if intervals[i][0] <= intervals[j][0] <= intervals[i][1] or intervals[i][0] <= intervals[j][1] <= intervals[i][1]:
                count += 1
    return count
