from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    accessed = []

    for op, key in operations:
        if op == 'get':
            if key in cache:
                accessed.append(key)
                cache.move_to_end(key)
                return (accessed, [cache[key]])
            else:
                return (accessed, [-1])
        elif op == 'put':
            if len(cache) >= capacity and key not in cache:
                cache.popitem(last=False)
            cache[key] = key
            accessed.append(key)

    return (accessed, [])
