from typing import List

def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    # Initialize the DP table with infinity for all values except 0
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    # Iterate over each coin and its limit
    for coin, limit in zip(coins, limits):
        # Update the DP table for each possible value up to the target
        for i in range(coin, target + 1):
            if i - coin >= 0:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    # If the target is still infinity, it means it's not possible to reach the target
    return dp[target] if dp[target] != float('inf') else -1

