def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    # Initialize a dictionary to store the league table
    league = defaultdict(lambda: [0, 0, 0])  # [wins, draws, losses]

    # Iterate over each match result
    for home_team, away_team, home_goals, away_goals in results:
        # Update the league table for the home team
        if home_goals > away_goals:
            league[home_team][0] += 1  # Win
        elif home_goals < away_goals:
            league[away_team][0] += 1  # Loss
        else:
            league[home_team][1] += 1  # Draw
            league[away_team][1] += 1  # Draw

        # Update the league table for the away team
        if home_goals > away_goals:
            league[away_team][2] += 1  # Loss
        elif home_goals < away_goals:
            league[home_team][2] += 1  # Win
        else:
            league[home_team][1] += 1  # Draw
            league[away_team][1] += 1  # Draw

    # Convert the defaultdict back to a list of tuples
    return sorted(league.items(), key=lambda x: (-x[1][0], -x[1][1], x[0]))
