def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    # Create a graph to represent the conflicts
    graph = {guest: set() for guest in guests}
    for conflict in conflicts:
        graph[conflict[0]].add(conflict[1])
        graph[conflict[1]].add(conflict[0])

    def is_valid_seating(arrangement: List[str]) -> bool:
        for i in range(len(arrangement)):
            for j in range(i + 1, len(arrangement)):
                if arrangement[i] in graph[arrangement[j]] or arrangement[j] in graph[arrangement[i]]:
                    return False
        return True

    def backtrack(start: int, arrangement: List[str]) -> List[List[str]]:
        if start == len(guests):
            if is_valid_seating(arrangement):
                return [arrangement]
            return []

        result = []
        for guest in guests[start:]:
            if guest not in arrangement:
                new_arrangement = arrangement + [guest]
                result.extend(backtrack(start + 1, new_arrangement))
        return result

    return backtrack(0, [])
