    for conflict in conflicts:
        graph[conflict[0]].add(conflict[1])
        graph[conflict[1]].add(conflict[0])

    def is_safe(seating: List[str], guest: str) -> bool:
        """Check if a guest can be seated without conflicts."""
        return all(seating[i] not in graph[guest] for i in range(len(seating)))

