        """Recursively try to seat guests."""
        if not guests_left:
            return [seating]

        result = []
        for guest in guests_left:
            if is_safe(seating, guest):
                new_seating = seating + [guest]
                remaining_guests = guests_left.copy()
                remaining_guests.remove(guest)
                result.extend(backtrack(new_seating, remaining_guests))

        return result

    # Start the backtracking process with an empty seating arrangement
    return backtrack([], guests)

