def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # Initialize two arrays to store increasing and decreasing lengths
    inc = [1] * n
    dec = [1] * n

    # Fill inc array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Fill dec array
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum value of inc[i] + dec[i] - 1
    return max(inc[i] + dec[i] - 1 for i in range(n))
