    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    def rotate_ring(start_row, start_col, end_row, end_col):
        ring = []
        # Collect elements in the ring
        for i in range(start_row, end_row + 1):
            ring.append(matrix[i][start_col])
        for j in range(start_col + 1, end_col + 1):
            ring.append(matrix[end_row][j])
        for i in range(end_row - 1, start_row - 1, -1):
            ring.append(matrix[i][end_col])
        for j in range(end_col - 1, start_col, -1):
            ring.append(matrix[start_row][j])

        # Rotate the ring
        k %= len(ring)
        if k < 0:
            k += len(ring)
        ring = ring[-k:] + ring[:-k]

        # Place the rotated ring back into the matrix
        index = 0
        for i in range(start_row, end_row + 1):
            result[i][start_col] = ring[index]
            index += 1
        for j in range(start_col + 1, end_col + 1):
