            for i in range(1, len(ring) - 1):
                ring[i], ring[i + 1] = ring[i + 1], ring[i]
        else:
            # Rotate counterclockwise
            ring[0], ring[-1] = ring[-1], ring[0]
            for i in range(len(ring) - 2, 0, -1):
                ring[i], ring[i - 1] = ring[i - 1], ring[i]

