def matrix_power_mod(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
    """
    Computes the power of a square matrix 'matrix' raised to the negative integer 'exp',
    taking the result modulo 'mod'. Returns a new matrix representing the result.

    Parameters:
    - matrix: A square matrix represented as a list of lists of integers.
    - exp: An integer representing the exponent to which the matrix is raised.
    - mod: An integer representing the modulus for the operation.

    Returns:
    - A new matrix representing the result of (matrix^exp) % mod.
    """
    if exp == 0:
        return [[0] * len(matrix) for _ in range(len(matrix))]

    def multiply_matrices(a: List[List[int]], b: List[List[int]], mod: int) -> List[List[int]]:
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_pow(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
        if exp == 1:
            return matrix
        half_exp = matrix_pow(matrix, exp // 2, mod)
        half_exp_squared = multiply_matrices(half_exp, half_exp, mod)
        if exp % 2 == 0:
            return half_exp_squared
        else:
            return multiply_matrices(half_exp_squared, matrix, mod)

    return matrix_pow(matrix, abs(exp), mod)

