    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize the queue with the starting position and the number of breaks used
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, breaks_used = queue.popleft()

        # Check if we reached the end
        if current == end:
            return breaks_used

        # Explore all four directions
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            # Check if the new position is within bounds
            if 0 <= nx < rows and 0 <= ny < cols:
                # If it's a breakable wall, try breaking it
                if grid[nx][ny] == '#' and breaks_used < 1:
                    new_position = (nx, ny)
                    if new_position not in visited:
                        visited.add(new_position)
                        queue.append((new_position, breaks_used + 1))
                # If it's an open space, move to it
                elif grid[nx][ny] == '.':
                    new_position = (nx, ny)
                    if new_position not in visited:
                        visited.add(new_position)
                        queue.append((new_position, breaks_used))

    # If we exhaust the queue without reaching the end, return -1
    return -1

