    def multiply_matrices(a, b, mod):
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] += a[i][k] * b[k][j]
                    result[i][j] %= mod
        return result

    def matrix_power(matrix, exp, mod):
        result = [[1] * len(matrix) for _ in range(len(matrix))]
        base = matrix
        while exp > 0:
            if exp % 2 == 1:
                result = multiply_matrices(result, base, mod)
            base = multiply_matrices(base, base, mod)
            exp //= 2
        return result

