    # Initialize the result as the identity matrix
    result = [[0] * len(matrix) for _ in range(len(matrix))]
    for i in range(len(matrix)):
        result[i][i] = 1

    # Base case: any matrix raised to the power of 0 is the identity matrix
    if exp == 0:
        return result

    # Helper function to multiply two matrices
    def multiply_matrices(a, b, mod):
        n = len(a)
        c = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % mod
        return c

    # Exponentiation by squaring
    while exp > 0:
        if exp % 2 == 1:
            result = multiply_matrices(result, matrix, mod)
        matrix = multiply_matrices(matrix, matrix, mod)
        exp //= 2

    return result

