            elif op == 'ne':
                return left != right
            else:
                raise ValueError(f"Unsupported operator: {op}")

        def visit_Compare(self, node):
            left = self.visit(node.left)
            ops = [op.__class__.__name__.lower() for op in node.ops]
            comparators = [self.visit(comp) for comp in node.comparators]
            if len(ops) != len(comparators) - 1:
                raise ValueError("Invalid comparison expression")
            for i, op in enumerate(ops):
                if op == 'lt':
                    if not left < comparators[i]:
                        return False
                elif op == 'le':
                    if not left <= comparators[i]:
                        return False
                elif op == 'gt':
                    if not left > comparators[i]:
                        return False
                elif op == 'ge':
                    if not left >= comparators[i]:
                        return False
                elif op == 'eq':
                    if not left == comparators[i]:
                        return False
                elif op == 'ne':
                    if not left != comparators[i]:
                        return False
                else:
                    raise ValueError(f"Unsupported operator: {op}")
