    assert solve_congruences([(1, 4), (2, 6)]) == None, "Test case 2 failed"
    assert solve_congruences([]) == (0, 1), "Test case 3 failed"
    assert solve_congruences([(0, 7), (5, 11)]) == (5, 77), "Test case 4 failed"
    print("All test cases passed!")

check_solution()
