import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match valid tokens in the expression
    token_pattern = re.compile(r'\b\d+(\.\d+)?|\+|-|\*|/|\(|\)|\^')

    # Function to apply an operation to two operands
    def apply_operation(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '^':
            values.append(left ** right)

    # Stack to hold operators
    operators = []
    # Stack to hold values
    values = []

    # Tokenize the expression
    tokens = token_pattern.findall(expression.replace(' ', ''))

    for token in tokens:
        if token.isdigit() or '.' in token:
            values.append(float(token))
        elif token in ('+', '-', '*', '/', '^'):
            while (operators and operators[-1] in ('*', '/', '^') and
                   precedence(operators[-1]) >= precedence(token)):
                apply_operation(operators, values)
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operation(operators, values)
            operators.pop()  # Remove the '('

    # Apply remaining operations
    while operators:
        apply_operation(operators, values)

    # The final value in the stack is the result
    if len(values) != 1:
        raise ValueError("Invalid expression")
    return values[0]

# Helper function to determine operator precedence
def precedence(op):
    if op in ('*', '/'):
        return 2
    elif op in ('+', '-'):
        return 1
    elif op == '^':
        return 3
    return 0
