def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        raise ValueError("Input string cannot be empty.")

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    if not all('0' <= char <= '9' or 'a' <= char <= 'z' for char in number):
        raise ValueError("Invalid character in input string.")

    if number == '0':
        return '0'

    # Convert from base to decimal
    decimal_value = 0
    for i, char in enumerate(reversed(number)):
        digit = ord(char) - (ord('0') if char.isdigit() else ord('a') - 10)
        decimal_value += digit * (from_base ** i)

    # Convert from decimal to target base
    if decimal_value == 0:
        return '0'

    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = chr(remainder + (ord('0') if remainder < 10 else ord('a') - 10)) + result
        decimal_value //= to_base

    if is_negative:
        result = '-' + result

    return result
