from collections import deque

def min_slides(grid: list[str]) -> int:
    # Find the starting and ending positions
    start = None
    end = None
    for i, row in enumerate(grid):
        for j, char in enumerate(row):
            if char == 'S':
                start = (i, j)
            elif char == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize the queue with the starting position and distance 0
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, distance = queue.popleft()

        # If we reached the end, return the distance
        if current == end:
            return distance

        # Explore all possible moves
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            # Check if the new position is within bounds and not a wall
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] != '#':
                # If the new position is not visited, add it to the queue
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), distance + 1))

    # If we exhaust the queue without reaching the end, return -1
    return -1
