import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}")

    # Define a visitor to evaluate the AST
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_Name(self, node):
            if node.id not in record:
                raise ValueError(f"Key '{node.id}' not found in record")
            return record[node.id]

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.FloorDiv):
                return left // right
            elif isinstance(node.op, ast.Mod):
                return left % right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            else:
                raise ValueError(f"Unsupported binary operation: {node.op}")

        def visit_Compare(self, node):
            left = self.visit(node.left)
            results = []
            for op, right in zip(node.ops, node.comparators):
                if isinstance(op, ast.Eq):
                    results.append(left == right)
                elif isinstance(op, ast.NotEq):
                    results.append(left != right)
                elif isinstance(op, ast.Lt):
                    results.append(left < right)
                elif isinstance(op, ast.LtE):
                    results.append(left <= right)
                elif isinstance(op, ast.Gt):
                    results.append(left > right)
                elif isinstance(op, ast.GtE):
                    results.append(left >= right)
                else:
                    raise ValueError(f"Unsupported comparison operation: {op}")
            return all(results)

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return operand
            elif isinstance(node.op, ast.Not):
                return not operand
            else:
                raise ValueError(f"Unsupported unary operation: {node.op}")

        def visit_Call(self, node):
            if node.func.id != 'len':
                raise ValueError("Only 'len' function is supported")
            if len(node.args) != 1:
                raise ValueError("Len function takes exactly one argument")
            arg = self.visit(node.args[0])
            if not isinstance(arg, (int, list)):
                raise ValueError("Len function argument must be an integer or list")
            return len(arg)

        def visit_Expr(self, node):
            return self.visit(node.value)

    # Evaluate the expression
    evaluator = ExpressionEvaluator()
    try:
        result = evaluator.visit(tree.body)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

    return result
