                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                values.append(left / right)
            elif operator == '**':
                values.append(left ** right)
            elif operator == 'sqrt':
                values.append(math.sqrt(right))
            elif operator == 'abs':
                values.append(abs(right))
            elif operator == 'sin':
                values.append(math.sin(right))
            elif operator == 'cos':
                values.append(math.cos(right))

        def evaluate(tokens):
            values = []
            operators = []
            i = 0
            while i < len(tokens):
                token = tokens[i]
                if token.isdigit():
                    values.append(float(token))
                elif token in ['+', '-', '*', '/', '**', 'sqrt', 'abs', 'sin', 'cos']:
                    while (operators and operators[-1] != '(' and
                           ((token == '*' or token == '/') and
                            (operators[-1] == '*' or operators[-1] == '/')) or
                           ((token == '+' or token == '-') and
                            (operators[-1] == '+' or operators[-1] == '-')) or
                           (token == '**' and operators[-1] == '**')):
                        apply_operator(operators, values)
                    operators.append(token)
                elif token == '(':
                    operators.append(token)
                elif token == ')':
                    while operators[-1] != '(':
                        apply_operator(operators, values)
                    operators.pop()  # Remove '('
                i += 1
            while operators:
                apply_operator(operators, values)
            return values[0]

        tokens = formula.replace(' ', '').split()
        return evaluate(tokens)

    try:
        return parse_expression(formula.split(','))
    except ZeroDivisionError as e:
        raise ValueError(f"Error evaluating formula: {e}")
    except Exception as e:
        raise ValueError(f"Invalid formula: {e}")

