from collections import deque

def min_slides(grid: list[str]) -> int:
    # Find the starting and exit positions
    start = None
    end = None
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == 'S':
                start = (i, j)
            elif cell == 'E':
                end = (i, j)

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize the queue with the starting position and move count
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, moves = queue.popleft()

        # If we reached the exit, return the number of moves
        if current == end:
            return moves

        # Explore all possible moves
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            # Check if the new position is within bounds and not a wall
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] != '#':
                # If the new position hasn't been visited, add it to the queue
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), moves + 1))

    # If we exhaust the queue without finding the exit, return -1
    return -1
