from typing import List, Tuple

def schedule_jobs(jobs: List[Tuple[str, int, int]]) -> List[str]:
    # Sort jobs by profit in descending order and by index in ascending order for ties
    jobs.sort(key=lambda x: (-x[2], x[0]))

    # Initialize a dictionary to keep track of available slots
    available_slots = {i: True for i in range(1, max(job[1] for job in jobs) + 1)}

    # Initialize the result list
    result = []

    # Schedule each job
    for job_name, deadline, profit in jobs:
        for slot in range(deadline, 0, -1):
            if available_slots[slot]:
                available_slots[slot] = False
                result.append(f"{job_name} {slot}")
                break

    return result

