import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression")

    # Define a visitor to evaluate the AST
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_Name(self, node):
            if node.id not in record:
                raise ValueError(f"Unknown variable '{node.id}'")
            return record[node.id]

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

        def visit_Compare(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            op = node.ops[0]
            if isinstance(op, ast.Eq):
                return left == right
            elif isinstance(op, ast.NotEq):
                return left != right
            elif isinstance(op, ast.Lt):
                return left < right
            elif isinstance(op, ast.LtE):
                return left <= right
            elif isinstance(op, ast.Gt):
                return left > right
            elif isinstance(op, ast.GtE):
                return left >= right
            else:
                raise ValueError(f"Unsupported comparison operator '{op.__class__.__name__}'")

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            elif isinstance(op, ast.Sub):
                return left - right
            elif isinstance(op, ast.Mult):
                return left * right
            elif isinstance(op, ast.Div):
                return left / right
            elif isinstance(op, ast.FloorDiv):
                return left // right
            elif isinstance(op, ast.Mod):
                return left % right
            elif isinstance(op, ast.Pow):
                return left ** right
            else:
                raise ValueError(f"Unsupported binary operator '{op.__class__.__name__}'")

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            op = node.op
            if isinstance(op, ast.USub):
                return -operand
            elif isinstance(op, ast.UAdd):
                return operand
            elif isinstance(op, ast.Not):
                return not operand
            else:
                raise ValueError(f"Unsupported unary operator '{op.__class__.__name__}'")

        def visit_Call(self, node):
            if node.func.id != 'not':
                raise ValueError("Only 'not' is supported as a unary operator")
            arg = self.visit(node.args[0])
            return not arg

    # Evaluate the AST
    evaluator = ExpressionEvaluator()
    return evaluator.visit(tree)

