def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order, then by original index
    jobs.sort(key=lambda x: (-x[1], jobs.index(x)))

    # Initialize a dictionary to keep track of available intervals
    intervals = {i: None for i in range(1, max(j[2] for j in jobs) + 1)}

    # Schedule jobs
    scheduled_jobs = []
    for name, deadline, profit in jobs:
        for i in range(deadline, 0, -1):
            if intervals[i] is None:
                intervals[i] = name
                scheduled_jobs.append(name)
                break

    return scheduled_jobs

