def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        return "0"

    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    if not all(c.isalnum() and c.lower() in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid characters in the input number.")

    # Convert from base from_base to decimal
    decimal_value = 0
    for char in number:
        digit = char.lower()
        if digit.isdigit():
            value = int(digit)
        else:
            value = ord(digit) - ord('a') + 10
        decimal_value = decimal_value * from_base + value

    # Convert from decimal to base to_base
    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result = str(remainder) + result
        else:
            result = chr(ord('a') + remainder - 10) + result
        decimal_value //= to_base

    if negative:
        result = '-' + result

    return result
