def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program Counter

    while pc < len(program):
        instruction = program[pc]

        if instruction.startswith('PUSH'):
            try:
                value = int(instruction.split()[1])
                if len(stack) >= 1000:
                    raise ValueError("Stack overflow")
                stack.append(value)
            except ValueError:
                raise ValueError(f"Invalid PUSH instruction: {instruction}")

        elif instruction == 'POP':
            if not stack:
                raise RuntimeError("POP from empty stack")
            stack.pop()

        elif instruction == 'DUP':
            if not stack:
                raise RuntimeError("DUP from empty stack")
