import re

def is_public_ip(ip_str: str) -> bool:
    # Regular expression for validating IPv4 addresses
    ipv4_pattern = r'^(\d{1,3}\.){3}\d{1,3}$'

    # Regular expression for validating IPv6 addresses
    ipv6_pattern = r'^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}(:[0-9a-fA-F]{1,4})?$'

    # Check if the input matches either IPv4 or IPv6 pattern
    if re.match(ipv4_pattern, ip_str):
        # Split the IPv4 address into its components
        parts = ip_str.split('.')
        # Check if all parts are between 0 and 255
        for part in parts:
            if not (0 <= int(part) <= 255):
                return False
        return True
    elif re.match(ipv6_pattern, ip_str):
        # Check if the IPv6 address is not in a private range
        if ip_str.startswith('fe80:') or ip_str.startswith('::1') or ip_str.startswith('::'):
            return False
        # Check if the IPv6 address contains a valid IPv4 mapping
        if '::ffff:' in ip_str:
            parts = ip_str.split('::ffff:')
            if len(parts) != 2 or not re.match(ipv4_pattern, parts[1]):
                return False
        return True
    else:
        return False
