import re

def evaluate_expression(expr: str) -> int:
    def apply_operator(operators, values):
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left // right)
        elif op == '^':
            values.append(left ** right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        if op == '^':
            return 3
        return 0

    expr = re.sub(r'\s+', '', expr)  # Remove all spaces
    values = []
    operators = []
    i = 0
    while i < len(expr):
        if expr[i] == '(':
            operators.append(expr[i])
        elif expr[i].isdigit():
            num = ''
            while i < len(expr) and expr[i].isdigit():
                num += expr[i]
                i += 1
            values.append(int(num))
            i -= 1
        elif expr[i] in ('+', '-', '*', '/', '^'):
            while (operators and operators[-1] != '(' and
                   precedence(operators[-1]) >= precedence(expr[i])):
                apply_operator(operators, values)
            operators.append(expr[i])
        elif expr[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

# Example usage:
