        elif parts[0] == "ADD":
            if len(stack) < 2:
                return None
            stack[-1] += stack.pop()
        elif parts[0] == "SUB":
            if len(stack) < 2:
                return None
            stack[-1] -= stack.pop()
        elif parts[0] == "MUL":
            if len(stack) < 2:
                return None
            stack[-1] *= stack.pop()
        elif parts[0] == "JMP":
            try:
