            source, target, amount = args
            if source in balances and target not in balances:
                fee = amount * 0.02
                if balances[source] >= amount + fee:
                    balances[source] -= amount + fee
                    balances[target] += amount
                else:
                    failed.append(i)
            else:
                failed.append(i)
        elif op == 'freeze':
            account = args[0]
            if account in balances:
                balances[account] = -balances[account]
            else:
                failed.append(i)
        elif op == 'unfreeze':
            account = args[0]
            if account in balances and balances[account] < 0:
                balances[account] = -balances[account]
            else:
                failed.append(i)

    return balances, failed
